// AssemblyScript SDK: goal vocabulary + call-goal wire shape.
//
// Answers, from the node's own declarations (../../goal-vocabulary.json,
// generated by infrix-core, never hand-edited):
//
//   1. Does the SDK name exactly the goals the node accepts (the GOAL_* constants)?
//   2. Does Governance.submitIntent reach the host through an import the platform
//      EXPORTS, passing the goal type and the parameter map the way the node
//      reads them?
//
// (2) runs the REAL compiled AssemblyScript (build/submit-probe.wasm, built by
// `npm run asbuild:probe` from test/submit-probe.ts) against a recording host
// import and inspects what it passed. The host is the only thing stubbed; the code
// under test is not.
//
// infrix-core's pkg/release SDKGoalParity fence feeds test/goal-emissions.json to
// the node's own admission validator. Refresh it after an intentional change with
//   INFRIX_UPDATE_GOAL_EMISSIONS=1 node --test test/goal-wire.test.mjs

import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const pkgRoot = join(here, '..');
const vocabulary = JSON.parse(readFileSync(join(pkgRoot, '..', 'goal-vocabulary.json'), 'utf8'));
const declarations = new Map(vocabulary.goals.map((g) => [g.goal, g]));
const governanceSource = readFileSync(join(pkgRoot, 'assembly', 'governance.ts'), 'utf8');
const probePath = join(pkgRoot, 'build', 'submit-probe.wasm');
const emissionsPath = join(here, 'goal-emissions.json');

// ---------------------------------------------------------------------------
// Vocabulary
// ---------------------------------------------------------------------------

function goalConsts(source) {
  return [...source.matchAll(/export const (GOAL_[A-Z0-9_]+)\s*:\s*string\s*=\s*"([^"]*)"\s*;/g)].map((m) => ({
    name: m[1],
    value: m[2],
  }));
}

test('the GOAL_* constants are exactly the node vocabulary, in both directions', () => {
  const consts = goalConsts(governanceSource);
  assert.ok(consts.length > 0, 'no GOAL_* constants were found, so the test is not reading the source');
  for (const c of consts) assert.equal(c.name, `GOAL_${c.value}`, `${c.name} carries ${c.value}`);
  const have = new Set(consts.map((c) => c.value));
  assert.equal(have.size, consts.length, 'a GOAL_* constant is declared twice');
  const cannotName = [...declarations.keys()].filter((g) => !have.has(g)).sort();
  const refused = [...have].filter((g) => !declarations.has(g)).sort();
  assert.deepEqual(cannotName, [], `an AssemblyScript contract cannot name ${cannotName.length} goal(s) the node accepts`);
  assert.deepEqual(refused, [], `the SDK names ${refused.length} goal(s) the node REFUSES`);
});

// ---------------------------------------------------------------------------
// Wire shape: the requirement semantics mirror the node's GoalFieldSpec.Check /
// FieldPresent (pkg/intent/goal_params.go).
// ---------------------------------------------------------------------------

function present(params, key) {
  const v = params?.[key];
  if (v === undefined || v === null) return false;
  if (typeof v === 'string') return v.trim() !== '';
  return true;
}

function shapeProblems(goal, params) {
  const decl = declarations.get(goal);
  if (!decl) return [`${goal} is not a goal the node accepts`];
  const problems = [];
  for (const group of decl.required) {
    const ok = group.some((alt) => alt.split('+').every((k) => present(params, k)));
    if (!ok) problems.push(`${goal}: missing required param ${group.length === 1 ? JSON.stringify(group[0]) : 'one of ' + group.join(' | ')}`);
  }
  for (const refused of decl.refusedKeys) {
    if (params && Object.prototype.hasOwnProperty.call(params, refused)) problems.push(`${goal}: the node refuses the key ${JSON.stringify(refused)} by name`);
  }
  return problems;
}

/** Instantiate the probe against a host whose host_intent_submit is `onSubmit`. */
async function instantiateProbe(onSubmit) {
  const bytes = readFileSync(probePath);
  const module = await WebAssembly.compile(bytes);
  const calls = [];
  let exp;
  const imports = {
    infrix: {
      host_intent_submit(goalPtr, goalLen, paramsPtr, paramsLen, outPtr, outMax) {
        const mem = new Uint8Array(exp.memory.buffer);
        const rec = {
          goalType: Buffer.from(mem.slice(goalPtr, goalPtr + goalLen)).toString('utf8'),
          paramsJSON: Buffer.from(mem.slice(paramsPtr, paramsPtr + paramsLen)).toString('utf8'),
          outMax,
        };
        calls.push(rec);
        const r = onSubmit(rec);
        if (r.code < 0) return r.code;
        const idBytes = Buffer.from(r.id, 'utf8');
        mem.set(idBytes, outPtr);
        return idBytes.length;
      },
    },
  };
  const instance = await WebAssembly.instantiate(module, imports);
  exp = instance.exports;
  const submit = (goalType, paramsJSON) => {
    const g = Buffer.from(goalType, 'utf8');
    const p = Buffer.from(paramsJSON, 'utf8');
    const base = exp.scratchPtr();
    const mem = new Uint8Array(exp.memory.buffer);
    mem.set(g, base);
    mem.set(p, base + g.length);
    const n = exp.submit(g.length, p.length);
    if (n < 0) return null;
    return Buffer.from(new Uint8Array(exp.memory.buffer).slice(base, base + n)).toString('utf8');
  };
  return { module, calls, submit };
}

test('submitIntent reaches the host through host_intent_submit, the import the platform exports', async () => {
  const { module } = await instantiateProbe(() => ({ code: 0, id: '' }));
  const imports = WebAssembly.Module.imports(module).map((i) => `${i.module}.${i.name}`);
  assert.deepEqual(
    imports,
    ['infrix.host_intent_submit'],
    'the probe must import exactly host_intent_submit; host_governance_submit_intent is not exported by the platform, so a module importing it fails to link',
  );
});

test('submitIntent passes the goal type and the parameter map as separate host arguments, verbatim', async () => {
  const params = '{"contract":"acc://alice.acme/counter","function":"increment","args":"[]"}';
  const { calls, submit } = await instantiateProbe(() => ({ code: 0, id: 'intent-child-1' }));
  const id = submit('CONTRACT_CALL', params);
  assert.equal(id, 'intent-child-1');
  assert.equal(calls.length, 1);
  assert.equal(calls[0].goalType, 'CONTRACT_CALL', 'the goal type is its own argument');
  assert.equal(calls[0].paramsJSON, params, 'the parameter map reaches the host byte for byte');
  assert.ok(calls[0].outMax >= 64, 'the id buffer is too small to hold an intent id');
});

test('submitIntent returns null when the host refuses the submission', async () => {
  const { calls, submit } = await instantiateProbe(() => ({ code: -4 }));
  assert.equal(submit('CONTRACT_CALL', '{"contract":"c","function":"f"}'), null);
  assert.equal(calls.length, 1);
});

test('what submitIntent emits satisfies the node declaration, and goal-emissions.json records it', async () => {
  const params = { contract: 'acc://alice.acme/counter', function: 'increment', args: '[]' };
  const { calls, submit } = await instantiateProbe(() => ({ code: 0, id: 'intent-child-1' }));
  submit('CONTRACT_CALL', JSON.stringify(params));
  const emitted = { type: calls[0].goalType, customParams: JSON.parse(calls[0].paramsJSON) };
  assert.deepEqual(shapeProblems(emitted.type, emitted.customParams), []);

  const rendered = JSON.stringify({ emissions: [{ sdk: 'assemblyscript', helper: 'Governance.submitIntent', goal: emitted }] }, null, 2) + '\n';
  if (process.env.INFRIX_UPDATE_GOAL_EMISSIONS === '1') writeFileSync(emissionsPath, rendered);
  assert.deepEqual(
    JSON.parse(readFileSync(emissionsPath, 'utf8')),
    JSON.parse(rendered),
    'test/goal-emissions.json is stale: re-run with INFRIX_UPDATE_GOAL_EMISSIONS=1 and let infrix-core re-check it',
  );
});

test('the shape check is not blind: it flags a misnamed call target and a dropped parameter map', () => {
  assert.deepEqual(shapeProblems('CONTRACT_CALL', { contract: 'acc://a.acme', function: 'go' }), []);
  assert.match(shapeProblems('CONTRACT_CALL', { contract: 'acc://a.acme', method: 'go' }).join('\n'), /missing required param "function"/);
  assert.match(shapeProblems('CONTRACT_CALL', {}).join('\n'), /"contract"/);
  assert.match(shapeProblems('GOVERNED_TRANSFER', {}).join('\n'), /not a goal the node accepts/);
});

// ---------------------------------------------------------------------------
// Every goal named in the SDK's own source and documentation is a node goal.
// ---------------------------------------------------------------------------

function docFiles() {
  const out = [join(pkgRoot, 'README.md')];
  for (const dir of ['assembly']) {
    for (const name of readdirSync(join(pkgRoot, dir))) {
      const full = join(pkgRoot, dir, name);
      if (statSync(full).isFile() && name.endsWith('.ts')) out.push(full);
    }
  }
  return out;
}

function namedGoals(text) {
  return [...text.matchAll(/submitIntent\(\s*["']([A-Z][A-Z0-9_]*)["']/g)].map((m) => m[1]);
}

test('every goal the SDK source and README name in a submitIntent call is a node goal', () => {
  const problems = [];
  let seen = 0;
  for (const file of docFiles()) {
    for (const goal of namedGoals(readFileSync(file, 'utf8'))) {
      seen++;
      if (!declarations.has(goal)) problems.push(`${file}: submitIntent("${goal}") names a goal the node refuses`);
    }
  }
  assert.ok(seen >= 1, 'no submitIntent example was found, so the scan is not reading the docs');
  assert.deepEqual(problems, []);
  assert.deepEqual(namedGoals('Governance.submitIntent("GOVERNED_TRANSFER", x)'), ['GOVERNED_TRANSFER']);
});
